select t.slug, count(*) filter (where q.statement_id is null) as null_links, count(*) as n, (select count(*) from flashcards f join flashcard_sets fs on fs.id=f.set_id where fs.topic_id=t.id) as fc, (select length(sm.content) from study_materials sm where sm.topic_id=t.id and sm.material_type='notes' order by length(sm.content) desc limit 1) as notes_len from topics t left join quizzes z on z.topic_id=t.id left join questions q on q.quiz_id=z.id and q.difficulty='exam' where t.slug in ('pressure-density','energy-work-power','forces-motion','electricity-circuits','measurement-units') group by t.id, t.slug order by t.slug;
